INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Kodierungsstandard nur lateinische Zeichen umfasst?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Schriftsysteme enthalten"}, {"text": "Ja", "correct": false, "because": "International umfassend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Standard definiert eine universelle Zeichenkodierung?', 3, '[{"text": "Unicode", "correct": true, "because": "Grundlage für weltweite Zeichen"}, {"text": "ASCII", "correct": false, "because": "Nur Basiszeichen"}, {"text": "UTF-8", "correct": false, "because": "Kodierung, kein Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein universeller Kodierungsstandard?', 5, '[{"text": "Weltweite Zeichen", "correct": true, "because": "Alle Schriftsysteme"}, {"text": "Codepunkte", "correct": true, "because": "Nummerierte Zeichen"}, {"text": "Kompatibilität", "correct": true, "because": "Mit anderen Standards"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Er umfasst über 100.000 Zeichen. b) Er ist nur für englische Texte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist international"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Texte in einer Software kodiere?', 4, '[{"text": "Zeichensätze", "correct": false, "because": "Bestimmen Kodierung"}, {"text": "Codepunkte", "correct": false, "because": "Definieren Zeichen"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Kodierungsstandard nur für Programmierung ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Für alle Texte"}, {"text": "Ja", "correct": false, "because": "Universell nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kodierung ist mit diesem Standard kompatibel?', 3, '[{"text": "UTF-8", "correct": true, "because": "Implementiert Unicode"}, {"text": "ASCII", "correct": false, "because": "Nur Teilmenge"}, {"text": "Base64", "correct": false, "because": "Datenkodierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein universeller Zeichensatz?', 5, '[{"text": "Globale Nutzung", "correct": true, "because": "Alle Sprachen"}, {"text": "Einheitlichkeit", "correct": true, "because": "Standardisiert"}, {"text": "Interoperabilität", "correct": true, "because": "Systemübergreifend"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) er alle Schriftsysteme abdeckt und b) er nur lateinische Zeichen hat. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Texte international zu kodieren?', 4, '[{"text": "Codepunkte", "correct": false, "because": "Definieren Zeichen"}, {"text": "UTF-8", "correct": false, "because": "Kodierungsformat"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ASCII dasselbe wie dieser Standard?', 2, '[{"text": "Nein", "correct": true, "because": "ASCII ist Teilmenge"}, {"text": "Ja", "correct": false, "because": "Viel umfassender"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kodierungen nutzen diesen Standard?', 4, '[{"text": "UTF-8", "correct": true, "because": "Variable Länge"}, {"text": "UTF-16", "correct": true, "because": "16-Bit-Einheiten"}, {"text": "ASCII", "correct": false, "because": "Eigenständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass der Standard nur für Software ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Dokumente, Web"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem universellen Kodierungsstandard?', 3, '[{"text": "Globale Texte", "correct": true, "because": "Alle Zeichen darstellen"}, {"text": "Datenkompression", "correct": false, "because": "Anderer Zweck"}, {"text": "Designverbesserung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Er unterstützt Emojis. b) Er ist auf 256 Zeichen begrenzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist ASCII"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt UTF-8 dabei?', 4, '[{"text": "Kodiert Zeichen", "correct": true, "because": "Implementiert Standard"}, {"text": "Verschlüsselt Daten", "correct": false, "because": "Anderer Zweck"}, {"text": "Farbt Texte", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Standard nur für Englisch ist?', 2, '[{"text": "Nein", "correct": true, "because": "International"}, {"text": "Ja", "correct": false, "because": "Alle Sprachen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen den Standard nützlich?', 5, '[{"text": "Vielfalt", "correct": true, "because": "Alle Schriftsysteme"}, {"text": "Einheitlichkeit", "correct": true, "because": "Standardisiert"}, {"text": "Kompatibilität", "correct": true, "because": "Systemübergreifend"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat er nur 7-Bit-Zeichen?', 3, '[{"text": "Nein", "correct": true, "because": "Viel umfassender"}, {"text": "Ja", "correct": false, "because": "ASCII ist 7-Bit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zum Standard?', 4, '[{"text": "Software mit japanischen Zeichen", "correct": true, "because": "Globale Zeichen"}, {"text": "Nur ASCII-Texte", "correct": false, "because": "Begrenzt"}, {"text": "Datenkompression", "correct": false, "because": "Anderer Zweck"}]');
